# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GENİŞ AİLE BİREYLERİ VE İSİM TAMLAMASI (الْإِضَافَة)</text>\n  <rect x="25" y="55" width="310" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Akraba İsim Tamlamaları</text>\n  <text x="180" y="110" text-anchor="middle" font-size="14" fill="#1e3a8a">وَلَدُ الْعَمِّ : Amcanın oğlu</text>\n  <text x="180" y="140" text-anchor="middle" font-size="14" fill="#1e3a8a">بِنْتُ الْخَالَةِ : Teyzenin kızı</text>\n  <text x="180" y="170" text-anchor="middle" font-size="14" fill="#1e3a8a">وَلَدُ الْخَالِ : Dayının oğlu</text>\n  <text x="180" y="200" text-anchor="middle" font-size="14" fill="#1e3a8a">بِنْتُ الْعَمَّةِ : Halanın kızı</text>\n  <rect x="365" y="55" width="310" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Tamlama Kuralları ve Meslek Kalıbı</text>\n  <text x="520" y="110" text-anchor="middle" font-size="13" fill="#14532d">1. Kelime (Muzaf): ال takısı ve tenvin almaz</text>\n  <text x="520" y="140" text-anchor="middle" font-size="13" fill="#14532d">2. Kelime (Muzafun İleyh): Kesralı okunur</text>\n  <text x="520" y="170" text-anchor="middle" font-size="14" font-weight="bold" fill="#166534">رَبَّةُ الْبَيْتِ : Ev hanımı</text>\n  <text x="520" y="200" text-anchor="middle" font-size="12" fill="#475569">كَمْ عَمًّا لَكَ؟ (Kaç amcan var?)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MESLEKLER VE ÇALIŞMA YERİ DİYALOGLARI (أَيْنَ يَعْمَلُ / تَعْمَلُ؟)</text>\n  <rect x="25" y="55" width="205" height="180" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="127" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Soru Kalıpları</text>\n  <text x="127" y="112" text-anchor="middle" font-size="13" fill="#7f1d1d">مَا مِهْنَتُهُ؟ (Mesleği ne? - Eril)</text>\n  <text x="127" y="142" text-anchor="middle" font-size="13" fill="#7f1d1d">مَا مِهْنَتُهَا؟ (Mesleği ne? - Dişil)</text>\n  <text x="127" y="172" text-anchor="middle" font-size="13" fill="#7f1d1d">أَيْنَ يَعْمَلُ؟ (Nerede çalışıyor?)</text>\n  <text x="127" y="202" text-anchor="middle" font-size="13" fill="#7f1d1d">أَيْنَ تَعْمَلُ؟ (Nerede çalışıyor?)</text>\n  <rect x="247" y="55" width="205" height="180" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Olumlu ve Olumsuz Cevap</text>\n  <text x="350" y="112" text-anchor="middle" font-size="12" fill="#713f12">يَعْمَلُ فِي الْمَدْرَسَةِ</text>\n  <text x="350" y="132" text-anchor="middle" font-size="11" fill="#475569">(Okulda çalışıyor - Eril)</text>\n  <text x="350" y="162" text-anchor="middle" font-size="12" fill="#713f12">لَا تَعْمَلُ فِي الْمُسْتَشْفَى</text>\n  <text x="350" y="182" text-anchor="middle" font-size="11" fill="#475569">(Hastanede çalışmıyor - Dişil)</text>\n  <text x="350" y="210" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">مَاهِر (Maharetli) · نَشِيط (Çalışkan)</text>\n  <rect x="470" y="55" width="205" height="180" rx="8" fill="#f3e8ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="572" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Hedef Meslekler</text>\n  <text x="572" y="110" text-anchor="middle" font-size="12" fill="#581c87">مُعَلِّم / مُعَلِّمَة (Öğretmen)</text>\n  <text x="572" y="135" text-anchor="middle" font-size="12" fill="#581c87">مُمَرِّض / مُمَرِّضَة (Hemşire)</text>\n  <text x="572" y="160" text-anchor="middle" font-size="12" fill="#581c87">بَيْطَرِيّ (Veteriner) · فَلَّاح (Çiftçi)</text>\n  <text x="572" y="185" text-anchor="middle" font-size="12" fill="#581c87">مُحَامٍ (Avukat) · طَبَّاخ (Aşçı)</text>\n  <text x="572" y="210" text-anchor="middle" font-size="12" fill="#581c87">شُرْطِيّ (Polis) · ضَابِط (Subay)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ŞEMSİ-KAMERİ HARFLER VE AKRABALIK İLKELERİ</text>\n  <rect x="25" y="55" width="310" height="115" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="180" y="78" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Şemsi Harfler (الحروف الشمسية)</text>\n  <text x="180" y="102" text-anchor="middle" font-size="12" fill="#7c2d12">ت ث د ذ ر ز س ش ص ض ط ظ ل ن</text>\n  <text x="180" y="125" text-anchor="middle" font-size="11" fill="#475569">ال takısındaki Lam okunmaz, harf şeddelenir.</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#ea580c">Örnek: اَلشُّرْطِيُّ (Eş-şurtiyyü) · اَلضَّابِطُ (Ed-dâbitu)</text>\n  <rect x="365" y="55" width="310" height="115" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="520" y="78" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Kameri Harfler (الحروف القمرية)</text>\n  <text x="520" y="102" text-anchor="middle" font-size="12" fill="#164e63">ا ب ج ح خ ع غ ف ق ك م هـ و ي</text>\n  <text x="520" y="125" text-anchor="middle" font-size="11" fill="#475569">ال takısındaki Lam cezimli olarak açıkça okunur.</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#0891b2">Örnek: اَلْمُعَلِّمُ (El-muallimu) · اَلْفَلَّاحُ (El-fellâhu)</text>\n  <rect x="25" y="182" width="650" height="60" rx="8" fill="#fefce8" stroke="#ca8a04" stroke-width="1.5"/>\n  <text x="350" y="206" text-anchor="middle" font-size="15" font-weight="bold" fill="#854d0e">«اَلْأَقْرَبُونَ أَوْلَى بِالْمَعْرُوفِ»</text>\n  <text x="350" y="228" text-anchor="middle" font-size="12" fill="#713f12">"Akrabalar iyiliğe ve yardıma daha layıktır." (Sıla-i Rahim ve Akrabalık Bilinci)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
